// IMAGE: a slowly moving gradient. The [Canvas2D.js] tab draws over it, and this shader also reads that
// drawing as iCanvas2D, to give everything on it a soft glow.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 color = mix(vec3(0.05, 0.12, 0.2), vec3(0.2, 0.06, 0.25), uv.x + 0.2 * sin(iTime + 3. * uv.y));

  // Blur the Canvas2D layer by averaging it around this pixel, and add it as light.
  vec4 glow = vec4(0.);
  for (int ring = 1; ring <= 4; ring++) {
    for (int i = 0; i < 8; i++) {
      float angle = 6.2832 * (float(i) + 0.5 * float(ring)) / 8.;
      vec2 offset = vec2(cos(angle), sin(angle)) * float(ring) * 5. / iResolution;
      glow += texture(iCanvas2D, uv + offset);
    }
  }
  color += 0.5 * glow.rgb / 32.;
  fragColor = vec4(color, 1.);
}

