// CANVAS2D: a tour of the Canvas2D layer. It draws text and shapes over the [Image] shader, which also
// reads this drawing as iCanvas2D to give it a soft glow. [Shader inputs](docs/reference#canvas2d-layer) lists what you can use.
import planck from "planck";  // Built-in libraries come in with import lines at the top.

// setup runs once after each build. It works out a looping path here, which draw plays back;
// whatever it returns is `data` in draw.
function setup({duration}) {
  const random = seededRandom(3);  // The same numbers on every run.
  const wobbles = [1, 2, 3].map(k => ({k, size: 0.25 * random(), phase: 6.28 * random()}));
  const path = [];
  for (let i = 0; i <= 600; i++) {
    const t = 2 * Math.PI * i / 600;
    let r = 0.3;
    for (const w of wobbles) r += 0.1 * w.size * Math.sin(3 * w.k * t + w.phase);
    path.push([r * Math.cos(2 * t), r * Math.sin(3 * t)]);
  }

  // A small physics world: balls dropped into a box.
  const world = new planck.World({gravity: planck.Vec2(0, -10)});
  const box = world.createBody();
  for (const [a, b] of [[[0, 0], [4, 0]], [[0, 0], [0, 3]], [[4, 0], [4, 3]]]) {
    box.createFixture(planck.Edge(planck.Vec2(...a), planck.Vec2(...b)));
  }
  const balls = [];
  for (let i = 0; i < 7; i++) {
    const ball = world.createDynamicBody(planck.Vec2(0.6 + 0.45 * i, 3.5 + 0.7 * i));
    ball.createFixture(planck.Circle(0.25), {density: 1, restitution: 0.8});
    balls.push(ball);
  }
  return {path, duration, world, balls};
}

// A second canvas that's faded, never cleared, so what's drawn on it leaves a trail.
let trails = null;

// draw runs once a step, 60 times a second. Raw ctx sizes are in units of a canvas 1080 tall.
function draw(ctx, {time, frame, width, height, floats, textures, data}) {
  clear(ctx);  // Without this, each step draws over the last.

  // Text, with the fonts of the font textures.
  ctx.fillStyle = "white";
  ctx.font = "700 80px Inter";
  ctx.fillText("Hello, canvas", 90, 150);
  ctx.font = "300 36px Inter";
  ctx.fillText("JavaScript drawing over a shader", 94, 205);

  // A texture slot, drawn as a picture in a frame. [Textures] sets which image it is.
  if (textures[0]) {
    ctx.save();
    ctx.translate(width - 330, 230);
    ctx.rotate(0.06 * Math.sin(time));
    ctx.fillStyle = "white";
    ctx.fillRect(-190, -140, 380, 280);
    ctx.drawImage(textures[0], -175, -125, 350, 250);
    ctx.restore();
  }

  // drawList: nested lists in shader-style coordinates (y up, -1 to 1). Each petal is a sublist,
  // turned by its own Rotate, which doesn't affect the rest.
  const petal = Polygon({pts: [[0, 0], [0.07, 0.15], [0, 0.32], [-0.07, 0.15]], edge: true});
  drawList(ctx, [
    Translate({offset: [0, 0.05]}),
    Set({strokeStyle: "white", lineWidth: 0.006}),
    Array.from({length: 8}, (_, k) => [
      Rotate({angle: k * Math.PI / 4 + 0.5 * time}),
      Set({fillStyle: `hsla(${30 + 25 * k}, 90%, 65%, 0.75)`}),
      petal,
    ]),
    Set({fillStyle: "#ffe9a0"}),
    Disk({radius: 0.05, edge: true}),
  ]);

  // Trails: a dot follows the path from setup, on the second canvas.
  if (!trails) {
    trails = new OffscreenCanvas(ctx.canvas.width, ctx.canvas.height);
  }
  const tctx = trails.getContext("2d");
  tctx.setTransform(ctx.getTransform());  // The same units as ctx.
  tctx.globalCompositeOperation = "destination-out";
  tctx.fillStyle = "rgba(0, 0, 0, 0.04)";
  tctx.fillRect(0, 0, width, height);
  tctx.globalCompositeOperation = "source-over";
  const point = data.path[Math.floor(600 * time / data.duration) % 600];
  drawList(tctx, [
    Translate({offset: [-1.2, -0.2]}),
    Set({fillStyle: "#7fe7ff"}),
    Disk({center: point, radius: 10, radiusInPixels: true}),
  ]);
  ctx.drawImage(trails, 0, 0, width, height);

  // iFloat0 moves this ball along its track. It's animated on the [Timeline]; drag it in [Sliders].
  const x = -1.3 + 1.8 * floats[0];
  drawList(ctx, [
    Set({strokeStyle: "#ffffff60", fillStyle: "white", font: "500 30px Inter"}),
    AbsoluteLineWidth(6),
    Line({pts: [[-1.3, -0.82], [0.5, -0.82]]}),
    Set({fillStyle: "#ff7aa8"}),
    Disk({center: [x, -0.82], radius: 0.05}),
    Set({fillStyle: "white"}),
    Text({at: [x, -0.72], text: "iFloat0 = " + floats[0].toFixed(2), align: "center"}),
  ]);

  // The physics world moves on 1/60 s each step. Its metres are turned into canvas units here.
  data.world.step(1 / 60);
  ctx.save();
  ctx.translate(width - 440, 980);
  ctx.scale(90, -90);  // 90 units to a metre, with y up.
  ctx.strokeStyle = "white";
  ctx.lineWidth = 0.04;
  ctx.strokeRect(0, 0, 4, 3.2);
  data.balls.forEach((ball, i) => {
    const p = ball.getPosition();
    ctx.fillStyle = `hsl(${180 + 25 * i}, 80%, 65%)`;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 0.25, 0, 2 * Math.PI);
    ctx.fill();
  });
  ctx.restore();
}
